stageCss:
#stage .as-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ------------------------------------------------------------- top strip -- */
#stage .as-top{
  height:76px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 24px; border-radius:20px;
  background:rgba(20,27,43,.75); border:1.5px solid var(--border);
}
#stage .as-brand{ display:flex; align-items:center; gap:14px; flex:1; min-width:0; }
#stage .as-cart{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(240,166,74,.14); border:1.5px solid rgba(240,166,74,.4); color:var(--warn);
}
#stage .as-cart svg{ width:26px; height:26px; }
#stage .as-shop{
  color:var(--text-primary); font-family:var(--font-mono); font-size:23px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
/* Nothing here may wrap — at 1080px a wrapped counter collapses the strip. */
#stage .as-meta{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:10px; white-space:nowrap; }
#stage .as-orders{ color:#fff; font-family:var(--font-mono); font-size:30px; font-weight:700; font-variant-numeric:tabular-nums; }
#stage .as-orders-l{ color:var(--text-dim); font-size:21px; font-weight:600; }
#stage .as-health{
  align-self:center; margin-left:12px; display:flex; align-items:center; gap:9px;
  padding:8px 16px; border-radius:100px;
  border:1.5px solid rgba(63,185,80,.45); background:rgba(63,185,80,.1);
  transition:border-color .3s ease, background .3s ease;
}
#stage .as-health i{
  width:11px; height:11px; border-radius:50%; background:var(--success);
  box-shadow:0 0 12px var(--success); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .as-health b{ color:var(--success); font-family:var(--font-mono); font-size:20px; font-weight:700; }
#stage .as-health.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.12); }
#stage .as-health.bad i{ background:var(--danger); box-shadow:0 0 12px var(--danger); animation-duration:.7s; }
#stage .as-health.bad b{ color:var(--danger); }

/* ----------------------------------------------------------- scene stack -- */
#stage .as-body{ position:relative; flex:1; min-height:0; }
#stage .as-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.985); pointer-events:none;
  transition:opacity .34s ease, transform .34s cubic-bezier(.22,1,.36,1);
}
#stage .as-sc.on{ opacity:1; transform:none; }

/* ======================== SCENE 1 · the single server ==================== */
#stage #as-sc-one{ display:flex; gap:22px; align-items:stretch; }

#stage .as-room{
  position:relative; flex:1; min-width:0;
  display:flex; flex-direction:column; align-items:center; justify-content:center;
  padding:46px 30px 30px;
  border:2px dashed rgba(139,149,167,.4); border-radius:28px;
  background:rgba(20,27,43,.4);
  transition:border-color .35s ease, background .35s ease;
}
#stage .as-room.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.07); }
#stage .as-room.down{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.07); }
#stage .as-room-tag{
  position:absolute; top:-16px; left:28px; padding:5px 16px; border-radius:100px;
  background:var(--bg-deep); border:1.5px solid var(--border);
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px;
  font-weight:700; letter-spacing:1.6px; white-space:nowrap;
  transition:color .3s ease, border-color .3s ease;
}
#stage .as-room.down .as-room-tag{ color:var(--danger); border-color:rgba(244,74,106,.5); }

#stage .as-shoppers{ display:flex; flex-direction:column; align-items:center; gap:14px; width:100%; }
#stage .as-shoppers-h{ color:var(--text-dim); font-size:20px; font-weight:700; letter-spacing:2.4px; }
#stage .as-faces{ display:flex; gap:10px; }
#stage .as-face{
  width:58px; height:58px; border-radius:50%; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338);
  border:1.5px solid var(--border);
  color:var(--text-primary); font-family:var(--font-mono); font-size:22px; font-weight:700;
  transition:opacity .3s ease, filter .3s ease;
}
#stage .as-face-more{ background:rgba(58,160,255,.14); border-color:rgba(58,160,255,.4); color:var(--accent-1); font-size:18px; }
#stage .as-faces.leaving .as-face{ opacity:.3; filter:grayscale(1); }

/* The wire between shopper and server: a flowing pulse, or a cut. */
#stage .as-wire{ position:relative; height:62px; width:100%; display:flex; align-items:center; justify-content:center; }
#stage .as-wire i{
  position:relative; width:6px; height:100%; border-radius:3px; overflow:hidden;
  background:rgba(139,149,167,.22); transition:background .3s ease;
}
#stage .as-wire.flow i::after{
  content:""; position:absolute; left:0; right:0; height:24px; top:-24px;
  background:var(--accent-cyan); box-shadow:0 0 18px var(--accent-cyan);
  animation:as-drop 1s linear infinite;
}
#stage .as-wire .as-cut{
  position:absolute; opacity:0; transform:scale(.5);
  width:44px; height:44px; border-radius:50%;
  display:flex; align-items:center; justify-content:center;
  background:var(--bg-deep); border:2px solid var(--danger);
  color:var(--danger); font-size:24px; font-weight:800;
  transition:opacity .26s ease, transform .26s cubic-bezier(.22,1,.36,1);
}
#stage .as-wire.cut i{ background:rgba(244,74,106,.3); }
#stage .as-wire.cut .as-cut{ opacity:1; transform:scale(1); }

#stage .as-srv{
  position:relative; width:100%;
  display:flex; align-items:center; gap:18px; padding:22px 24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border); border-radius:22px;
  transition:border-color .3s ease, box-shadow .3s ease, opacity .3s ease;
}
#stage .as-srv-ic{
  width:60px; height:60px; border-radius:16px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.12); color:var(--accent-1);
  transition:background .3s ease, color .3s ease;
}
#stage .as-srv-ic svg{ width:32px; height:32px; }
#stage .as-srv-b{ display:flex; flex-direction:column; gap:5px; min-width:0; }
#stage .as-srv-b b{ color:#fff; font-size:30px; font-weight:800; letter-spacing:-.4px; }
#stage .as-srv-b span{ color:var(--text-dim); font-family:var(--font-mono); font-size:20px; }
#stage .as-srv.live{ border-color:rgba(58,160,255,.55); box-shadow:0 0 0 1px rgba(58,160,255,.28), 0 0 44px rgba(58,160,255,.2); }
#stage .as-srv.busy{ border-color:rgba(240,166,74,.6); box-shadow:0 0 0 1px rgba(240,166,74,.3), 0 0 44px rgba(240,166,74,.16); }
#stage .as-srv.busy .as-srv-ic{ background:rgba(240,166,74,.16); color:var(--warn); }
#stage .as-srv.down{ border-color:rgba(244,74,106,.6); box-shadow:0 0 0 1px rgba(244,74,106,.3), 0 0 44px rgba(244,74,106,.16); }
#stage .as-srv.down .as-srv-ic{ background:rgba(244,74,106,.16); color:var(--danger); }
#stage .as-srv.dark{ opacity:.45; }

#stage .as-badge{
  margin-left:auto; flex-shrink:0; padding:8px 16px; border-radius:9px;
  background:rgba(63,185,80,.14); border:1px solid rgba(63,185,80,.4);
  color:var(--success); font-family:var(--font-mono); font-size:19px; font-weight:700; letter-spacing:1.2px;
  white-space:nowrap; transition:background .3s ease, border-color .3s ease, color .3s ease;
}
#stage .as-badge.warn{ background:rgba(240,166,74,.16); border-color:rgba(240,166,74,.45); color:var(--warn); }
#stage .as-badge.bad{ background:rgba(244,74,106,.16); border-color:rgba(244,74,106,.45); color:var(--danger); }
#stage .as-badge.off{ background:rgba(139,149,167,.12); border-color:rgba(139,149,167,.32); color:var(--text-dim); }

/* Planned maintenance, arriving as an object rather than as a caption. */
#stage .as-wrench{
  position:absolute; top:-22px; right:-14px;
  width:62px; height:62px; border-radius:50%;
  display:flex; align-items:center; justify-content:center;
  background:var(--bg-deep); border:2px solid var(--warn); color:var(--warn);
  opacity:0; transform:scale(.4) rotate(-40deg);
  transition:opacity .3s ease, transform .34s cubic-bezier(.22,1,.36,1);
}
#stage .as-wrench svg{ width:32px; height:32px; }
#stage .as-wrench.show{ opacity:1; transform:scale(1) rotate(0deg); }
#stage .as-wrench.show{ animation:as-wobble 1.6s ease-in-out infinite .34s; }

#stage .as-host{
  margin-top:20px; width:100%; display:flex; align-items:center; gap:14px;
  padding:14px 20px; border-radius:16px;
  background:rgba(14,20,32,.7); border:1.5px dashed var(--border);
}
#stage .as-host-l{ color:var(--text-dim); font-size:18px; font-weight:700; letter-spacing:2px; }
#stage .as-host-t{ margin-left:auto; color:var(--text-dim); font-family:var(--font-mono); font-size:20px; font-weight:600; transition:color .3s ease; }
#stage .as-host.hot{ border-color:rgba(240,166,74,.5); }
#stage .as-host.hot .as-host-t{ color:var(--warn); }

/* ----------------------------------------------------------- the phone --- */
#stage .as-phone{
  width:296px; flex-shrink:0; border-radius:34px; overflow:hidden;
  background:#0b0f18; border:3px solid #232C40;
  display:flex; flex-direction:column;
  box-shadow:0 24px 60px rgba(0,0,0,.5);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .as-phone.err{ border-color:rgba(244,74,106,.6); box-shadow:0 0 0 1px rgba(244,74,106,.28), 0 24px 60px rgba(244,74,106,.18); }
#stage .as-ph-bar{
  height:54px; flex-shrink:0; display:flex; align-items:center; gap:7px; padding:0 16px;
  background:#161d2c; border-bottom:1.5px solid var(--border);
}
#stage .as-ph-bar i{ width:9px; height:9px; border-radius:50%; background:#2c3550; }
#stage .as-ph-bar span{ margin-left:6px; color:var(--text-dim); font-family:var(--font-mono); font-size:15px; }
#stage .as-ph-body{ position:relative; flex:1; min-height:0; }
#stage .as-ph-ok, #stage .as-ph-err{
  position:absolute; inset:0; padding:20px;
  transition:opacity .3s ease;
}
#stage .as-ph-ok{ display:flex; flex-direction:column; gap:14px; opacity:1; }
#stage .as-phone.err .as-ph-ok{ opacity:0; }
#stage .as-ph-hero{ height:150px; border-radius:16px; background:linear-gradient(140deg,#20304d,#182238); border:1.5px solid var(--border); }
#stage .as-ph-row{ display:flex; gap:12px; }
#stage .as-ph-row span{ flex:1; height:82px; border-radius:12px; background:#141b2b; border:1.5px solid var(--border); }
#stage .as-ph-buy{
  margin-top:auto; height:56px; border-radius:14px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(90deg, var(--accent-2), var(--accent-1));
  color:#fff; font-size:22px; font-weight:800;
}
#stage .as-ph-buy.tap{ animation:msd-punch .38s cubic-bezier(.22,1,.36,1); }
#stage .as-ph-err{
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:12px;
  text-align:center; opacity:0;
}
#stage .as-phone.err .as-ph-err{ opacity:1; }
#stage .as-ph-x{
  width:76px; height:76px; border-radius:50%;
  display:flex; align-items:center; justify-content:center;
  background:rgba(244,74,106,.14); border:2px solid rgba(244,74,106,.5); color:var(--danger);
}
#stage .as-ph-x svg{ width:40px; height:40px; }
#stage .as-ph-err b{ color:#fff; font-size:26px; font-weight:800; line-height:1.2; }
#stage .as-ph-err span{ color:var(--text-dim); font-size:19px; font-weight:500; }
#stage .as-ph-err em{
  margin-top:6px; padding:6px 14px; border-radius:8px; font-style:normal;
  background:rgba(244,74,106,.14); border:1px solid rgba(244,74,106,.35);
  color:var(--danger); font-family:var(--font-mono); font-size:18px; font-weight:700;
}

/* ================= SCENES 2-5 · the availability set ===================== */
#stage .as-cloud{
  position:relative; width:100%; height:100%;
  display:flex; flex-direction:column; gap:12px;
  padding:40px 24px 22px;
  border:2px solid rgba(58,160,255,.34); border-radius:30px;
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.1), transparent 60%), rgba(20,27,43,.42);
}
#stage .as-cloud-tag{
  position:absolute; top:-17px; left:26px; display:flex; align-items:center; gap:10px;
  padding:5px 18px; border-radius:100px;
  background:var(--bg-deep); border:1.5px solid rgba(58,160,255,.5);
  color:var(--accent-1); font-family:var(--font-mono); font-size:19px;
  font-weight:700; letter-spacing:1.6px; white-space:nowrap;
}
#stage .as-cloud-tag svg{ width:22px; height:22px; }

#stage .as-clients{ flex-shrink:0; display:flex; align-items:center; justify-content:center; gap:10px; }
#stage .as-clients-l{ margin-left:12px; color:var(--text-dim); font-family:var(--font-mono); font-size:20px; font-weight:600; white-space:nowrap; }

#stage .as-pipe{ flex-shrink:0; height:42px; display:flex; align-items:center; justify-content:center; }
#stage .as-pipe i{
  position:relative; width:6px; height:100%; border-radius:3px; overflow:hidden;
  background:rgba(139,149,167,.22);
}
#stage .as-pipe.flow i{ background:rgba(58,160,255,.28); }
#stage .as-pipe.flow i::after{
  content:""; position:absolute; left:0; right:0; height:18px; top:-18px;
  background:var(--accent-cyan); box-shadow:0 0 18px var(--accent-cyan);
  animation:as-drop .85s linear infinite;
}

#stage .as-lb{
  flex-shrink:0; display:flex; align-items:center; gap:18px; padding:18px 24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border); border-radius:22px;
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .as-lb.live{ border-color:rgba(58,160,255,.6); box-shadow:0 0 0 1px rgba(58,160,255,.3), 0 0 48px rgba(58,160,255,.22); }
#stage .as-lb-ic{
  width:58px; height:58px; border-radius:16px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.12); color:var(--accent-1);
  transition:background .3s ease, color .3s ease;
}
#stage .as-lb.live .as-lb-ic{ background:var(--accent-1); color:#0E1420; }
#stage .as-lb-ic svg{ width:32px; height:32px; }
#stage .as-lb-b{ display:flex; flex-direction:column; gap:4px; min-width:0; }
#stage .as-lb-b b{ color:#fff; font-size:29px; font-weight:800; letter-spacing:-.4px; }
#stage .as-lb-b span{ color:var(--text-dim); font-family:var(--font-mono); font-size:19px; }

/* ------------------------------------------------------------- fan-out --- */
#stage .as-fan{ position:relative; flex-shrink:0; height:64px; }
#stage .as-fan-svg{ width:100%; height:100%; display:block; overflow:visible; }
#stage .as-arm{
  fill:none; stroke:rgba(139,149,167,.3); stroke-width:4; stroke-linecap:round;
  transition:stroke .3s ease, opacity .3s ease;
}
#stage .as-arm.on{ stroke:var(--accent-1); stroke-dasharray:10 14; animation:msd-dash 1.1s linear infinite; }
#stage .as-arm.off{ stroke:rgba(244,74,106,.35); stroke-dasharray:6 10; animation:none; opacity:.55; }
#stage .as-pct{
  position:absolute; top:16px; padding:5px 14px; border-radius:100px; font-style:normal;
  background:var(--bg-deep); border:1.5px solid var(--border);
  color:var(--text-primary); font-family:var(--font-mono); font-size:20px; font-weight:700;
  opacity:0; transition:opacity .3s ease, color .3s ease, border-color .3s ease;
}
#stage .as-pct.show{ opacity:1; }
#stage .as-pct.hot{ color:var(--accent-1); border-color:rgba(58,160,255,.55); }
#stage .as-pct.dead{ color:var(--danger); border-color:rgba(244,74,106,.5); }
#stage .as-pct-l{ left:20%; }
#stage .as-pct-r{ right:20%; }

/* ------------------------------------------------------ availability set -- */
#stage .as-set{
  position:relative; flex:1; min-height:0;
  display:flex; flex-direction:column; gap:14px;
  padding:34px 22px 20px;
  border:2px dashed rgba(58,160,255,.4); border-radius:26px;
  background:rgba(14,20,32,.5);
  transition:border-color .35s ease, box-shadow .35s ease;
}
#stage .as-set.lit{ border-color:rgba(58,160,255,.7); box-shadow:0 0 0 1px rgba(58,160,255,.2), 0 0 60px rgba(58,160,255,.14); }
#stage .as-set-tag{
  position:absolute; top:-16px; left:24px; padding:5px 16px; border-radius:100px;
  background:var(--bg-deep); border:1.5px solid rgba(58,160,255,.5);
  color:var(--accent-1); font-family:var(--font-mono); font-size:19px;
  font-weight:700; letter-spacing:1.8px; white-space:nowrap;
}
#stage .as-vms{ flex:1; min-height:0; display:flex; gap:18px; }

#stage .as-vm{
  position:relative; flex:1; min-width:0;
  display:flex; flex-direction:column; gap:10px; padding:16px 18px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border); border-radius:20px;
  transition:border-color .3s ease, box-shadow .3s ease, opacity .3s ease;
}
#stage .as-vm.live{ border-color:rgba(63,185,80,.55); box-shadow:0 0 0 1px rgba(63,185,80,.25), 0 0 44px rgba(63,185,80,.16); }
#stage .as-vm.maint{ border-color:rgba(240,166,74,.65); box-shadow:0 0 0 1px rgba(240,166,74,.3), 0 0 44px rgba(240,166,74,.18); }
#stage .as-vm-h{ display:flex; align-items:center; gap:11px; }
#stage .as-vm-h b{ color:#fff; font-size:28px; font-weight:800; letter-spacing:-.3px; }
#stage .as-dot{
  width:13px; height:13px; border-radius:50%; flex-shrink:0;
  background:rgba(139,149,167,.5); transition:background .3s ease, box-shadow .3s ease;
}
#stage .as-vm.live .as-dot{ background:var(--success); box-shadow:0 0 14px var(--success); animation:msd-breathe 2.1s ease-in-out infinite; }
#stage .as-vm.maint .as-dot{ background:var(--warn); box-shadow:0 0 14px var(--warn); animation:msd-breathe .9s ease-in-out infinite; }
#stage .as-vm-st{
  margin-left:auto; padding:6px 13px; border-radius:8px; white-space:nowrap;
  background:rgba(139,149,167,.12); border:1px solid rgba(139,149,167,.3);
  color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:700;
  transition:background .3s ease, border-color .3s ease, color .3s ease;
}
#stage .as-vm.live .as-vm-st{ background:rgba(63,185,80,.14); border-color:rgba(63,185,80,.4); color:var(--success); }
#stage .as-vm.maint .as-vm-st{ background:rgba(240,166,74,.16); border-color:rgba(240,166,74,.45); color:var(--warn); }

#stage .as-vm-ic{
  position:relative; align-self:flex-start;
  width:68px; height:68px; border-radius:18px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.12); color:var(--accent-1);
  transition:background .3s ease, color .3s ease;
}
#stage .as-vm-ic svg{ width:36px; height:36px; }
#stage .as-vm.live .as-vm-ic{ background:rgba(63,185,80,.14); color:var(--success); }
#stage .as-vm.maint .as-vm-ic{ background:rgba(240,166,74,.16); color:var(--warn); }
#stage .as-tool{
  position:absolute; top:-14px; right:-16px;
  width:46px; height:46px; border-radius:50%;
  display:flex; align-items:center; justify-content:center;
  background:var(--bg-deep); border:2px solid var(--warn); color:var(--warn);
  opacity:0; transform:scale(.4) rotate(-40deg);
  transition:opacity .28s ease, transform .32s cubic-bezier(.22,1,.36,1);
}
#stage .as-tool svg{ width:24px; height:24px; }
#stage .as-tool.show{ opacity:1; transform:scale(1) rotate(0deg); animation:as-wobble 1.5s ease-in-out infinite .32s; }

#stage .as-vm-tags{ display:flex; gap:9px; flex-wrap:wrap; }
#stage .as-tag{
  padding:6px 13px; border-radius:8px; white-space:nowrap;
  font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:.6px;
  border:1px solid transparent; transition:box-shadow .3s ease, background .3s ease;
}
#stage .as-tag-fd{ background:rgba(34,211,238,.12); border-color:rgba(34,211,238,.34); color:var(--accent-cyan); }
#stage .as-tag-ud{ background:rgba(58,160,255,.12); border-color:rgba(58,160,255,.34); color:var(--accent-1); }
#stage .as-tag.ping{ animation:msd-flash .5s ease-out; }

#stage .as-gauge{ height:12px; border-radius:6px; background:rgba(139,149,167,.16); overflow:hidden; }
#stage .as-gauge i{
  display:block; width:0%; height:100%; border-radius:6px;
  background:linear-gradient(90deg, var(--accent-1), var(--accent-cyan));
  transition:width .55s cubic-bezier(.22,1,.36,1), background .3s ease;
}
#stage .as-gauge i.warn{ background:linear-gradient(90deg, var(--warn), #f7c77a); }

#stage .as-vm-f{ color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }

#stage .as-dom{ flex-shrink:0; display:flex; gap:12px; }
#stage .as-dom-c{
  flex:1; min-width:0; padding:11px 16px; border-radius:14px;
  background:rgba(20,27,43,.8); border:1.5px solid var(--border);
  color:var(--text-dim); font-size:19px; font-weight:600; line-height:1.3;
}
#stage .as-dom-c b{ display:block; color:var(--text-primary); font-size:20px; font-weight:800; margin-bottom:3px; }
#stage #as-dom-fd b{ color:var(--accent-cyan); }
#stage #as-dom-ud b{ color:var(--accent-1); }

/* --------------------------------------------------------- verdict strip -- */
#stage .as-strip{
  flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:14px 20px; border-radius:18px;
  background:rgba(20,27,43,.85); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .as-strip-l{
  flex-shrink:0; padding:6px 14px; border-radius:8px;
  background:rgba(139,149,167,.14); border:1px solid rgba(139,149,167,.32);
  color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:1.4px;
  transition:background .3s ease, border-color .3s ease, color .3s ease;
}
#stage .as-strip b{ color:var(--text-primary); font-size:24px; font-weight:700; line-height:1.25; }
#stage .as-strip.good{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.09); }
#stage .as-strip.good .as-strip-l{ background:rgba(63,185,80,.16); border-color:rgba(63,185,80,.45); color:var(--success); }
#stage .as-strip.good b{ color:#fff; }
#stage .as-strip.warn{ border-color:rgba(240,166,74,.5); background:rgba(240,166,74,.08); }
#stage .as-strip.warn .as-strip-l{ background:rgba(240,166,74,.16); border-color:rgba(240,166,74,.45); color:var(--warn); }

/* ========================== SCENE 6 · the payoff ========================= */
#stage .as-win{
  width:100%; height:100%;
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:14px;
  padding:30px 34px;
  border:2px solid rgba(63,185,80,.4); border-radius:30px;
  background:radial-gradient(circle at 50% 12%, rgba(63,185,80,.12), transparent 60%), rgba(20,27,43,.5);
}
#stage .as-win-check{
  width:104px; height:104px; border-radius:50%; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(63,185,80,.16); border:3px solid var(--success); color:var(--success);
  opacity:0; transform:scale(.5);
  transition:opacity .34s ease, transform .42s cubic-bezier(.22,1,.36,1);
}
#stage .as-win-check svg{ width:52px; height:52px; }
#stage .as-win-check.show{ opacity:1; transform:scale(1); box-shadow:0 0 0 8px rgba(63,185,80,.1), 0 0 60px rgba(63,185,80,.32); }
#stage .as-win-h{ color:#fff; font-size:46px; font-weight:900; letter-spacing:-.8px; text-align:center; }
#stage .as-win-s{ color:var(--text-dim); font-family:var(--font-mono); font-size:22px; font-weight:600; }
#stage .as-win-list{ width:100%; display:flex; flex-direction:column; gap:11px; margin-top:8px; }
#stage .as-win-i{
  display:flex; align-items:center; gap:15px; padding:15px 20px; border-radius:16px;
  background:rgba(20,27,43,.85); border:1.5px solid var(--border);
}
#stage .as-win-i i{
  width:36px; height:36px; border-radius:50%; flex-shrink:0; font-style:normal;
  display:flex; align-items:center; justify-content:center;
  background:rgba(63,185,80,.16); border:1.5px solid rgba(63,185,80,.45);
  color:var(--success); font-size:20px; font-weight:800;
}
#stage .as-win-i b{ color:var(--text-primary); font-size:26px; font-weight:700; }
#stage .as-win-sla{
  margin-top:4px; display:flex; align-items:center; gap:14px;
  padding:13px 22px; border-radius:100px;
  background:rgba(58,160,255,.1); border:1.5px solid rgba(58,160,255,.42);
}
#stage .as-win-sla b{ color:var(--accent-1); font-family:var(--font-mono); font-size:30px; font-weight:800; }
#stage .as-win-sla span{ color:var(--text-dim); font-size:20px; font-weight:600; }

